const getAshtakScoreColor = (score, isTotal) => {
  if (isTotal) {
    if (score >= 30) return '#2e7d32';
    if (score >= 25) return '#e65100';
    return '#c0392b';
  } else {
    // per-planet max is 8
    if (score >= 5) return '#2e7d32';
    if (score >= 3) return '#e65100';
    return '#c0392b';
  }
};

